use std::sync::mpsc;

fn main() {
    let (tx, rx) = mpsc::channel();
    let s = String::from("a");
    tx.send(s).unwrap();
    println!("{s}");
    println!("{}", rx.recv().unwrap());
}

use std::sync::mpsc;

fn main() {
    let (tx, rx) = mpsc::channel();
    for i in 1..=3 {
        tx.send(i * i).unwrap();
    }
    drop(tx);
    let v: Vec<i32> = rx.iter().collect();
    println!("{v:?}");
}

use std::sync::mpsc;
use std::thread;

fn main() {
    let (tx, rx) = mpsc::channel();
    let hs: Vec<_> = (1..=3)
        .map(|i| {
            let tx = tx.clone();
            thread::spawn(move || tx.send(i).unwrap())
        })
        .collect();
    drop(tx);
    for h in hs {
        h.join().unwrap();
    }
    let mut v: Vec<i32> = rx.iter().collect();
    v.sort();
    println!("{v:?} {}", v.len());
}
